<?php
namespace App\Livewire\Admin\Analytics;use App\Services\AdminAnalyticsService;use Livewire\Attributes\Url;use Livewire\Component;
class Staff extends Component{#[Url]public string $from='';#[Url]public string $to='';public function mount():void{abort_unless(auth()->user()->isAdmin()||(auth()->user()->isSales()&&auth()->user()->isManager()),403);$this->from=$this->from?:now()->subDays(30)->toDateString();$this->to=$this->to?:today()->toDateString();}public function render(AdminAnalyticsService $service){$rows=$service->staff($this->from,$this->to);if(!auth()->user()->isAdmin())$rows=$rows->whereIn('id',auth()->user()->teamMembers()->pluck('id')->push(auth()->id()));return view('livewire.admin.analytics.staff',compact('rows'))->layout('components.layouts.admin',['title'=>'Staff performance']);}}
